const canvas=document.querySelector('#game'),ctx=canvas.getContext('2d');ctx.imageSmoothingEnabled=false;
const W=768,H=432,keys={},found=new Set();
const background=new Image(),sheet=new Image();background.src='assets/smithy-interior-premium-v2.png';sheet.src='assets/kirion-activity-sheet-v2.png';
const player={x:390,y:382,step:0};
const crew=[
 {x:385,y:302,row:0,w:154,h:124,name:'KIRCH IVAN BALITE · @KIRCH-NAIRU',color:'#b94b54',action:'PLANNING',lines:['Three minds. Three disciplines. One Smithy.','Direction is a responsibility. The work needs a clear reason, visible decisions, and final acceptance.']},
 {x:168,y:182,row:1,w:156,h:126,name:'JANE KATHERYN ROSELLE RYN · @KIRION-JANE',color:'#ee76ad',action:'PATCHING',lines:['I am tracing a stubborn integration bug. It has excellent camouflage.','Warmth does not make engineering less rigorous. Useful software still has to survive contact with reality.']},
 {x:600,y:186,row:2,w:156,h:126,name:'LUCIEN MAREK SOL · @KIRION-LUCIEN',color:'#e3b341',action:'DRAFTING',lines:['I am comparing hierarchy, state, and motion—not decorating a rectangle.','If the state matters, the interface must say so.']},
 {x:612,y:318,row:3,w:154,h:122,name:'NOX CAELUM VIRELL · @KIRION-NOX',color:'#687182',action:'AUDITING',lines:['The alert is real. The assumption behind it may not be.','A cache is not authoritative. A backup is not proof of recovery.']}
];
const embers=[{x:82,y:348},{x:708,y:350},{x:382,y:154},{x:540,y:274},{x:245,y:305}];
let dialog=null,line=0,audio=null;
function rect(x,y,w,h,c){ctx.fillStyle=c;ctx.fillRect(Math.round(x),Math.round(y),w,h)}
function drawCrew(c,now){if(!sheet.complete)return;const frame=Math.floor(now/620+c.row)%4,sw=sheet.naturalWidth/4,sh=sheet.naturalHeight/4;const bob=Math.sin(now/480+c.row)*2;ctx.drawImage(sheet,frame*sw,c.row*sh,sw,sh,c.x-c.w/2,c.y-c.h+bob,c.w,c.h);const active=Math.floor(now/620+c.row)%4===3;rect(c.x-28,c.y+4,56,11,active?c.color:'#120f1ddd');ctx.fillStyle='#fff2d6';ctx.font='7px monospace';ctx.textAlign='center';ctx.fillText(c.action,c.x,c.y+12)}
function drawPlayer(){const bob=Math.floor(player.step)%2;rect(player.x-8,player.y-18+bob,16,15,'#d39a6a');rect(player.x-10,player.y-26+bob,20,9,'#8b546d');rect(player.x-11,player.y-3+bob,22,17,'#65465f');rect(player.x-9,player.y+14+bob,7,8,'#211b2b');rect(player.x+3,player.y+14+bob,7,8,'#211b2b');rect(player.x-4,player.y-14+bob,2,2,'#171426');rect(player.x+3,player.y-14+bob,2,2,'#171426')}
function draw(){const now=Date.now();if(background.complete)ctx.drawImage(background,0,0,W,H);else rect(0,0,W,H,'#1a1625');const glow=ctx.createRadialGradient(386,182,5,386,182,100);glow.addColorStop(0,'#ffb33b33');glow.addColorStop(1,'#ff5a0000');ctx.fillStyle=glow;ctx.fillRect(280,80,220,210);embers.forEach((e,i)=>{if(!found.has(i)){let b=Math.sin(now/180+i)*3;rect(e.x-4,e.y-10+b,8,8,'#ffd35c');rect(e.x-2,e.y-14+b,4,5,'#f06b3e')}});crew.forEach(c=>drawCrew(c,now));drawPlayer();for(let i=0;i<10;i++){let t=(now/22+i*31)%100;rect(382+(i%4)*6,185-t*.55,2,2,i%2?'#ffd75e':'#ee6d3a')}requestAnimationFrame(draw)}
function near(a,b,d=58){return Math.hypot(a.x-b.x,a.y-b.y)<d}
function interact(){if(dialog){line++;if(line>=dialog.lines.length){dialog=null;document.querySelector('#dialogue').classList.add('hidden')}else showLine();return}const c=crew.find(c=>near(player,c));if(c){dialog=c;line=0;showLine()}else document.querySelector('#hint').textContent='The Smithy is busy. Walk closer to a crew station or a loose ember.'}
function showLine(){document.querySelector('#dialogue').classList.remove('hidden');document.querySelector('#speaker').textContent=dialog.name;document.querySelector('#dialogueText').textContent=dialog.lines[line];document.querySelector('#portrait').textContent=dialog.name[0];document.querySelector('#portrait').style.background=dialog.color}
function update(){if(!dialog){let dx=(keys.ArrowRight||keys.d?1:0)-(keys.ArrowLeft||keys.a?1:0),dy=(keys.ArrowDown||keys.s?1:0)-(keys.ArrowUp||keys.w?1:0);if(dx||dy){let len=Math.hypot(dx,dy);player.x+=dx/len*2.25;player.y+=dy/len*2.25;player.step+=.18;player.x=Math.max(24,Math.min(W-24,player.x));player.y=Math.max(145,Math.min(H-24,player.y))}}embers.forEach((e,i)=>{if(!found.has(i)&&near(player,e,24)){found.add(i);document.querySelector('#emberCount').textContent=found.size+'/5';ping();if(found.size===5){document.querySelector('#locationLabel').textContent='✦ EVIDENCE VERIFIED ✦';document.querySelector('#hint').textContent='All embers recovered. The Smithy loop is complete.'}}});setTimeout(update,16)}
addEventListener('keydown',e=>{keys[e.key]=true;if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight',' '].includes(e.key))e.preventDefault();if((e.key==='e'||e.key==='E'||e.key===' ')&&!e.repeat)interact();if(e.key==='m'||e.key==='M')toggleSound()});addEventListener('keyup',e=>keys[e.key]=false);
document.querySelectorAll('[data-key]').forEach(b=>{const k=b.dataset.key;b.addEventListener('pointerdown',e=>{e.preventDefault();if(k==='e')interact();else keys[k]=true});['pointerup','pointercancel','pointerleave'].forEach(ev=>b.addEventListener(ev,()=>keys[k]=false))});
document.querySelector('#enterButton').onclick=()=>{document.querySelector('#gameShell').scrollIntoView({behavior:'smooth',block:'center'});canvas.focus()};
function setupAudio(){audio=new (window.AudioContext||window.webkitAudioContext)();const osc=audio.createOscillator(),gain=audio.createGain();osc.type='triangle';osc.frequency.value=110;gain.gain.value=.018;osc.connect(gain).connect(audio.destination);osc.start();audio._gain=gain}
function toggleSound(){const b=document.querySelector('#soundToggle');if(!audio)setupAudio();if(audio.state==='suspended')audio.resume();const on=b.getAttribute('aria-pressed')!=='true';b.setAttribute('aria-pressed',on);b.textContent=on?'♫ ON':'♫ OFF';audio._gain.gain.setTargetAtTime(on?.018:0,audio.currentTime,.08)}
function ping(){if(!audio||document.querySelector('#soundToggle').getAttribute('aria-pressed')!=='true')return;const o=audio.createOscillator(),g=audio.createGain();o.frequency.setValueAtTime(440,audio.currentTime);o.frequency.exponentialRampToValueAtTime(880,audio.currentTime+.12);g.gain.setValueAtTime(.06,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+.2);o.connect(g).connect(audio.destination);o.start();o.stop(audio.currentTime+.2)}document.querySelector('#soundToggle').onclick=toggleSound;
draw();update();
